  // Sets the editability to assist in editing the grid

  if (!parent.isEditMode) return;
  var relshipNd = parent.item.selectSingleNode("Relationships/Item[@id='" + relationshipID + "' and related_id/Item]");
  if (!relshipNd) return;
  var relatedNd = relshipNd.selectSingleNode("related_id/Item");

  //+++++ Get the values
  var isPart = false;
  var new_item_id = relatedNd.selectSingleNode("new_item_id/Item");
  if (new_item_id)
    isPart = (new_item_id.getAttribute("type") == "Part")
  else
  {
    var icon = aras.getItemProperty(relatedNd, "affected_type", undefined);
    isPart = (icon != undefined && icon.indexOf("Part") > 0);
  }
  
  var action = aras.getItemProperty(relatedNd, "action", undefined);
  var isInter = (aras.getItemProperty(relatedNd, "interchangeable") == "1");
  var isAdd = (action == "Add");
  var isChange = (action == "Change");
  var isDelete = (action == "Delete");
  //----- Get the values

  if (propertyName == "action")
  {
    var doUpdateRow = false;
    if (isAdd)
    {
      // Old Number, Old Rev should be empty
      clearItemPropVal(relatedNd, "affected_id");
      clearItemPropVal(relatedNd, "affected_rev");
      clearItemPropVal(relatedNd, "in_build_disposition");
      clearItemPropVal(relatedNd, "in_service_disposition");
      doUpdateRow = true;
    }
    else if (isDelete)
    {
      clearItemPropVal(relatedNd, "new_item_id");
      clearItemPropVal(relatedNd, "new_item_rev")
      doUpdateRow = true;
    }
    
    if (isAdd || (isChange && !isInter))
    {
      // New Number, New Rev should be empty
      clearItemPropVal(relatedNd, "new_item_id");
      clearItemPropVal(relatedNd, "new_item_rev");
      clearItemPropVal(relatedNd, "affected_type");
      doUpdateRow = true;
    }
    if (doUpdateRow) updateRow(relshipNd, relatedNd);
  }
  else
  {
    var hash = { affected_id: !isAdd, interchangeable: isChange, new_item_id: (isAdd || (isChange && !isInter)), in_build_disposition: (isPart && !isAdd), in_service_disposition: (isPart && !isAdd) };
    if (hash[propertyName] !== undefined)
    {
      return hash[propertyName];
    }
  }

  function clearItemPropVal(itm, propNm)
  {
    var propNd = itm.selectSingleNode(propNm);
    if (propNd)
    {
      itm.removeChild(propNd);
      itm.appendChild(itm.ownerDocument.createElement(propNm));
    }
  }

var affectedId = getRelatedItemProperty(relationshipID, 'affected_id');
var newItemId = getRelatedItemProperty(relationshipID, 'new_item_id');
if(!affectedId || !newItemId) return;

function getType(id)
{
  var qryXml = "<Item type='Change Controlled Item' id='" + id + "' action='get' select='id'/>";
  var qry = new Item();
  qry.loadAML(qryXml);
  var result = qry.apply();
  if(result.isError()) { aras.AlertError(aras.getResource("plm", "checkaffectedtype.can_not_get", id)); return null; }
  return result.getAttribute("type");
}

var affectedIdType = getType(affectedId);
if(!affectedIdType) return;
var newItemIdType = getType(newItemId);
if(!newItemIdType) return;

if(affectedIdType != newItemIdType)
{
  aras.AlertError(aras.getResource("plm", "checkaffectedtype.same_affected_superseding_numbers", affectedIdType, newItemIdType));
  setRelatedItemProperty(relationshipID, 'affected_type','<img src="../images/Delete.svg">');
}
else
{
  var qryXml = "<Item type='ItemType' action='get' select='open_icon'><name>" + affectedIdType + "</name></Item>";
  var qry = new Item();
  qry.loadAML(qryXml);
  var result = qry.apply();
  var icon = result.getProperty("open_icon");
  setRelatedItemProperty(relationshipID, 'affected_type','<img src="' + icon + '">');
}

if(propertyName != "affected_id" && propertyName != "new_item_id")
{
  alert("Error: Use this method for affected_id or new_item_id properties");
  return;
}

var relationshipType = item.selectSingleNode("Relationships/Item[@id='" + relationshipID + "']");
if(!relationshipType)
{
  aras.AlertError(aras.getResource("", "ui_methods_ex.failed_to_get_item", "RelationshipType with id " + relationshipID));   
  return; 
}

var relationshipTypeName = relationshipType.getAttribute('type');

if(relationshipTypeName != "Express ECO Affected Item" && relationshipTypeName != "Express DCO Affected Item")
{
  //Nothing doing if unknown relationship.
  return; 
}

var propertyValue = getRelatedItemProperty(relationshipID, propertyName);

if(!propertyValue)
{
	//If property value is empty, then do nothing.
  return;
}

var propertyValueType = getType(propertyValue);

if(!propertyValueType)
{
  //If property value is empty, then do nothing.
  return;
}

if(!ValidatePropertyValue())
{
  //Reset invalid value in DOM and Grid
  gridApplet.GetSelectedCell().SetValue("");
  setRelatedItemProperty(relationshipID, propertyName, "");  
  aras.AlertError(aras.getResource("plm", "affecteditem.invaliditemtype_for_relationshipitem", relationshipTypeName, propertyValueType)); 
  return;
}
  
// --------functions Implementation---------
function ValidatePropertyValue()
{      
  if(!propertyValueType)
  {
    return false;
  }
    
  if(relationshipTypeName == "Express ECO Affected Item" && propertyValueType == "Part")
  {
    return true; 
  }
    
  if(relationshipTypeName == "Express DCO Affected Item" && (propertyValueType == "Document" || propertyValueType == "CAD"))
  {
    return true;
  }
    
  return false;
}
      
function getType(id)
{
  var qryXml = "<Item type='Change Controlled Item' id='" + id + "' action='get' select='id'/>";
  var qry = new Item();
  qry.loadAML(qryXml);
  var result = qry.apply();
  if(result.isError()) 
  { 
    aras.AlertError(aras.getResource("plm", "checkaffectedtype.can_not_get", id)); 
    return null; 
  }
  return result.getAttribute("type");
}

