if(propertyName != "affected_id" && propertyName != "new_item_id")
{
  alert("Error: Use this method for affected_id or new_item_id properties");
  return;
}

var relationshipType = item.selectSingleNode("Relationships/Item[@id='" + relationshipID + "']");
if(!relationshipType)
{
  aras.AlertError(aras.getResource("", "ui_methods_ex.failed_to_get_item", "RelationshipType with id " + relationshipID));   
  return; 
}

var relationshipTypeName = relationshipType.getAttribute('type');

if(relationshipTypeName != "Express ECO Affected Item" && relationshipTypeName != "Express DCO Affected Item")
{
  //Nothing doing if unknown relationship.
  return; 
}

var propertyValue = getRelatedItemProperty(relationshipID, propertyName);

if(!propertyValue)
{
	//If property value is empty, then do nothing.
  return;
}

var propertyValueType = getType(propertyValue);

if(!propertyValueType)
{
  //If property value is empty, then do nothing.
  return;
}

if(!ValidatePropertyValue())
{
  //Reset invalid value in DOM and Grid
  gridApplet.GetSelectedCell().SetValue("");
  setRelatedItemProperty(relationshipID, propertyName, "");  
  aras.AlertError(aras.getResource("plm", "affecteditem.invaliditemtype_for_relationshipitem", relationshipTypeName, propertyValueType)); 
  return;
}
  
// --------functions Implementation---------
function ValidatePropertyValue()
{      
  if(!propertyValueType)
  {
    return false;
  }
    
  if(relationshipTypeName == "Express ECO Affected Item" && propertyValueType == "Part")
  {
    return true; 
  }
    
  if(relationshipTypeName == "Express DCO Affected Item" && (propertyValueType == "Document" || propertyValueType == "CAD"))
  {
    return true;
  }
    
  return false;
}
      
function getType(id)
{
  var qryXml = "<Item type='Change Controlled Item' id='" + id + "' action='get' select='id'/>";
  var qry = new Item();
  qry.loadAML(qryXml);
  var result = qry.apply();
  if(result.isError()) 
  { 
    aras.AlertError(aras.getResource("plm", "checkaffectedtype.can_not_get", id)); 
    return null; 
  }
  return result.getAttribute("type");
}

string new_item_id = this.getProperty("new_item_id");
if(string.IsNullOrEmpty(new_item_id))
{
  return this;
}

string versionedItemId;
Aras.Server.Core.InnovatorDatabase conn = CCO.Variables.InnDatabase;
string itemTypeDbName = CCO.DB.GenerateTableName("Change Controlled Item");

Aras.Server.Core.Utilities.IsIdValid(new_item_id, true);

string sqlQuery = "SELECT TOP(1) last_version.ID FROM " + itemTypeDbName + " cur_version INNER JOIN " + itemTypeDbName + " last_version ON cur_version.id = '" + conn.QuoteValue(new_item_id) + "' and cur_version.config_id = last_version.config_id and last_version.is_current = '1'";

Aras.Server.Core.InnovatorDataSet result = conn.ExecuteSelect(sqlQuery);

if (result.RowsNumber <= 0)
{
	const string errorString = "Item last version is not found.";
	const string errorDetail = "config_id = '{0}'";
	Item errorItem = this.getInnovator().newError(errorString);
	errorItem.setErrorDetail(string.Format(errorDetail,new_item_id));
	return errorItem;
}

versionedItemId = result["id"].ToString();

if(versionedItemId == new_item_id)
{
  return this;
}

Item callframe = this.newItem("SQL","SQL PROCESS");
callframe.setProperty("name","affectedItemFloatNewItem");
callframe.setProperty("PROCESS","CALL");
callframe.setProperty("ARG1", this.getID());
callframe.setProperty("ARG2", versionedItemId);
callframe = callframe.apply();
  
return callframe;

Aras.Server.Security.Identity plmIdentity = Aras.Server.Security.Identity.GetByName("Aras PLM");
bool PermissionWasSet  = Aras.Server.Security.Permissions.GrantIdentity(plmIdentity);

try
{
	Action<string,IEnumerable<string>,string> execUpdateFlag = (itemType,idList,ignoredAffItemID) => 
			{
				String itemTypeDbName = String.Empty;

				if (!String.IsNullOrEmpty(itemType))
				{
					itemTypeDbName = CCO.DB.GenerateTableName(itemType);
				}

				Aras.Server.Core.InnovatorDatabase conn = CCO.Variables.InnDatabase;

				foreach (String itemID in idList)
				{
					string sqlQueryFormat = "exec update_has_change_pending_flag '" + itemTypeDbName + "','" + itemID + "','" + ignoredAffItemID + "'";
					conn.ExecuteSQL(sqlQueryFormat);
				}
			};

  string thisType = this.getType();
	List<String> itemIDs = new List<String>();
	string itemTypeName = String.Empty;
  string ignoredAffectedItemID = String.Empty;
  
  Item affectedItem = null;

  switch(thisType)
  {
